const saveRows=arrangement.save.bind(arrangement);arrangement.save=next=>{if(JSON.stringify(next)===JSON.stringify(arrangement.rows))return;saveRows(next);timeline.record({label:'Song',undo:()=>arrangement.undo(),redo:()=>arrangement.redo()});};
const endMotion=motion.end.bind(motion),clearMotion=motion.clear.bind(motion),recordMotion=()=>timeline.record({label:'Motion',undo:()=>motion.undo(),redo:()=>motion.redo()});
