function recordParameter(c){sendParameter(c);if(view==='sound'&&nativeSoundMode){const key=soundKey(c.id),state=nativeSound()?.snapshot();if(key&&state?.phase==='ready'&&c.after!==state.values.get(key))runSoundAction({kind:'change',key,value:c.after});return;}if(view==='mix'&&nativeMixMode&&runtimeMixKey(c.id)){if(nativeMix.snapshot().phase==='ready'&&c.after!==nativeMix.snapshot().values.get(runtimeMixKey(c.id)))nativeMixAction(nativeMix.change(runtimeMixKey(c.id),c.after),'Emulator edit not confirmed');return;}restoreMixPreview(c.id);if(c.before===c.after)return;const group=mixAliasIndex.byId.get(c.id);if(group){const edit=mixChange(group,parameterDraft,c.after);edit.redo();timeline.record({label:c.label||'Mix',undo:edit.undo,redo:edit.redo});return;}const source=findSpec(c.id),identity={label:c.label||source.label,context:c.context||source.context};parameterIdentity.set(c.id,identity);parameterDraft.set(c.id,c.after);timeline.record({label:[identity.context,identity.label].filter(Boolean).join(' · '),undo:()=>parameterDraft.set(c.id,c.before),redo:()=>parameterDraft.set(c.id,c.after)});}
