if(typeof window!=='undefined'&&window.addEventListener)window.addEventListener('resize',()=>{fitted=false;if(view==='roll')paintNotes();});

// The Web lane stages the qualified shared runtime under /emu/. No fallback
// simulator is substituted when that deployment is unavailable.
const localInstrument=createLocalInstrument({
 load:async options=>{const baseURL=new URL('../emu/',import.meta.url);const {loadNativeSession,createNativeControlProvider,createNativeSoundProvider}=await import(new URL('native-session.mjs',baseURL).href);nativeProviderFactory=createNativeControlProvider;nativeSoundFactory=createNativeSoundProvider;return loadNativeSession({...options,baseURL});},
 attach:attachEnvelopeObserver,status,onState:phase=>{localInstrumentPhase=phase;if(phase!=='running'){retireNativeSound();++nativeMixGeneration;nativeMixMode=false;nativeMix.close();}if(['mix','sound'].includes(view))other();}
});

// ---- DnBOX Remote: connection, drum steps, BREAK steps, tempo, keybed, double-tap reset ----
var remoteLink=remoteLink??null;
function drumPart(){const p=$('part')?.value;return p==='drum909'||p==='drum808';}
function accentsFor(kit){accentsFor.s??={'909':Array(64).fill(false),'808':Array(64).fill(false)};return accentsFor.s[kit];}
function drumSeq(kit){drumSeq.s??={};return drumSeq.s[kit]??={page:0,params:false,values:{},extra:DRUM_VOICES[kit].map(()=>Array(64).fill(false))};}
function seqShared(){return seqShared.s??={};}
function drumValues(kit){const d=optionDefaults(drumOptions());return {...d,...seqShared(),...drumSeq(kit).values};}
function setDrumOption(kit,pref,v){const o=drumOptions().find(x=>x.pref===pref);if(!o||!Number.isInteger(v)||v<0||v>o.max)return;const store=o.scope==='part'?drumSeq(kit).values:seqShared(),before=store[pref];const apply=x=>{if(x===undefined)delete store[pref];else store[pref]=x;sendEdit(optionEdit(o,kit==='808'?'drum808':'drum909',currentPattern(),x??o.default));if(view==='drums')other();};if((before??o.default)===v)return;apply(v);timeline.record({label:o.label,undo:()=>apply(before),redo:()=>apply(v)});status(o.label+' · '+formatOption(o,v));}
function toggleExtraStep(kit,voice,step){const st=drumSeq(kit),row=st.extra[voice];if(!row||step<PAGE_STEPS||step>=64)return;const apply=on=>{row[step]=on;sendEdit(drumStepEdit(kit==='808'?'drum808':'drum909',currentPattern(),voice,step,on));if(view==='drums')other();};const before=row[step];apply(!before);timeline.record({label:'Step',undo:()=>apply(before),redo:()=>apply(!before)});}
const currentPattern=()=>Math.max(0,(Number(String($('pattern-no')?.textContent).replace(/\D/g,''))||1)-1);
const sendEdit=edit=>{if(remoteLink?.connected())void remoteLink.send(edit);};
function sendDrumHit(track,note,start){const on=model.notes.some(n=>n.track===track&&n.note===note&&n.start===start);const kit=track==='drum808'?'808':'909',voice=DRUM_VOICES[kit].findIndex(v=>v[1]===note),step=Math.round(start*16/trace.endSample);if(voice>=0&&step>=0&&step<16)sendEdit(drumStepEdit(track,currentPattern(),voice,step,on));}
function toggleAccent(track,step){const kit=track==='drum808'?'808':'909',a=accentsFor(kit),apply=v=>{a[step]=v;sendEdit(drumStepEdit(track,currentPattern(),ACCENT_TRACK,step,v));if(view==='drums')other();};const before=a[step];apply(!before);timeline.record({label:'Accent',undo:()=>apply(before),redo:()=>apply(!before)});}
function sendParameter(c){if(!remoteLink?.connected()||!c||!Number.isInteger(Number(c.after)))return;const pref=prefFromId(c.id);if(pref)sendEdit(paramEdit(pref,Number(c.after)));}
var bassPresets=[0,0];
function bassValues(slot){bassValues.s??=[new Map(),new Map()];return bassValues.s[slot];}
function sendBassChoice(slot){const k=FIRMWARE_ENGINES.prefKinds,e=FIRMWARE_ENGINES.bassEngines.find(x=>x.name===(soundBanks[slot]==='JUNO'?'SUPERJ6':soundBanks[slot]));if(!e)return;sendEdit(paramEdit({kind:k.R_BENGINE,a:0,b:slot,c:0},e.kind));sendEdit(paramEdit({kind:k.R_BPRESET,a:0,b:slot,c:0},Math.min(255,bassPresets[slot])));}
$('other-view').addEventListener('change',e=>{const t=e.target;if(t.dataset.firmwareParam===undefined)return;const slot=soundSlot(),i=Number(t.dataset.firmwareParam),v=Number(t.value);if(slot<0||!Number.isInteger(v))return;const m=bassValues(slot),before=m.get(i);const apply=x=>{if(x===undefined)m.delete(i);else m.set(i,x);sendEdit(paramEdit(bassParamPref(slot,i),x??Number(t.dataset.default)));if(view==='sound')other();};apply(v);timeline.record({label:t.getAttribute('aria-label')||'Sound',undo:()=>apply(before),redo:()=>apply(v)});});
$('other-view').addEventListener('input',e=>{const t=e.target;if(t.dataset.firmwareParam===undefined)return;const out=t.closest('.funkybeats-typed-unit')?.querySelector('[data-param-value]');if(out)out.textContent=t.value;});
{const prev=$('part').onchange;$('part').onchange=()=>{prev();if((view==='roll'||view==='drums')&&(drumPart()?'drums':'roll')!==view)setView('roll');};}
if(breakEditor){const orig=breakEditor.paint;let last=structuredClone(breakSequence);breakEditor.paint=()=>{orig();for(const c of changedBreakSteps(last,breakSequence))sendEdit(breakStepEdit(currentPattern(),c.step,c.on,c.slice));if(last.rate!==breakSequence.rate){const r=BREAK_RATE_VALUE[breakSequence.rate];if(r!==undefined)sendEdit(paramEdit({kind:FIRMWARE_ENGINES.prefKinds.R_BRKRATE,a:0,b:currentPattern()+1,c:0},r));}last=structuredClone(breakSequence);};}
{const root=document.querySelector('.tempo-ctl'),display=$('tempo');if(root?.querySelectorAll&&display){const fe=FIRMWARE_ENGINES;mountTempoControl({root,display,initial:fe.defaultTempo,defaultBpm:fe.defaultTempo,min:fe.tempoRange[0],max:fe.tempoRange[1],onChange:bpm=>{sendEdit(tempoEdit(bpm));status('Tempo · '+bpm+' BPM');}});}}
if($('pitch-rail')?.style&&scroll)mountKeybedScroll({rail:$('pitch-rail'),scroll,row:()=>row,onTap:note=>{const part=$('part').value;if(!remoteLink?.connected()||!['chicago','miami'].includes(part))return;const on=padOn(part,note,100);if(on.ok){remoteLink.sendMidi(on.bytes);setTimeout(()=>{const off=padOff(part,note);if(off.ok)remoteLink.sendMidi(off.bytes);},250);}}});
if(document.body)mountResetGesture({root:document.body,onReset:r=>{if(r.kind==='range'){applyRangeReset(r.el,r.value);return;}const inDrums=!!r.el.closest('#drum-lane'),list=inDrums?drumLaneNotes():notes(),groups=stepGroups(list,trace.endSample),group=groups[r.step];if(!group?.notes.length)return;cancelStepLane();for(const n of groups.flatMap(g=>g.notes))laneBases.set(n.id,laneBases.get(n.id)??n.note);const id=-77;if(laneGesture.begin(id,group,laneKind(),{groups})){selected=group.notes[0].id;laneGesture.preview(id,laneDefault(laneKind()),r.step);laneGesture.end(id);}}});

var BREAK_RATE_VALUE={'1/16':0,'1/8':1,'1/4':2};

// Drum step pages, the parameter page and its options (before the generic other-view handlers).
{const kitOf=()=>$('part').value==='drum808'?'808':'909';
$('other-view').addEventListener('click',e=>{const b=e.target.closest?.('button');if(!b||view!=='drums')return;const kit=kitOf(),st=drumSeq(kit);
 if(b.dataset.drumPage!==undefined){st.page=Number(b.dataset.drumPage);st.params=false;}
 else if(b.dataset.drumParams!==undefined){st.params=!st.params;}
 else if(b.dataset.seqOpt!==undefined){setDrumOption(kit,b.dataset.seqOpt,Number(b.dataset.seqValue));e.stopPropagation();return;}
 else if(b.dataset.drumStep!==undefined){toggleExtraStep(kit,Number(b.dataset.drumVoice),Number(b.dataset.drumStep));e.stopPropagation();status();return;}
 else return;
 e.stopPropagation();other();},true);
$('other-view').addEventListener('input',e=>{const t=e.target;if(t.dataset?.seqOpt===undefined||t.tagName!=='INPUT')return;e.stopPropagation();const o=drumOptions().find(x=>x.pref===t.dataset.seqOpt),out=t.closest('.seq-opt')?.querySelector('output');if(o&&out)out.textContent=formatOption(o,Number(t.value));},true);
$('other-view').addEventListener('change',e=>{const t=e.target;if(t.dataset?.seqOpt===undefined||t.tagName!=='INPUT')return;e.stopPropagation();setDrumOption(kitOf(),t.dataset.seqOpt,Number(t.value));},true);}
